package ru.screenrecorder.app;
import android.content.*;import android.media.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.MediaStore;import java.nio.*;import java.util.*;
final class Trim{
 static Uri copy(Context c,Uri input,double from,double to)throws Exception{
  MediaExtractor probe=new MediaExtractor();probe.setDataSource(c,input,null);int video=-1;long length=0;for(int t=0;t<probe.getTrackCount();t++){MediaFormat f=probe.getTrackFormat(t);if(f.getString(MediaFormat.KEY_MIME).startsWith("video/")){video=t;length=f.getLong(MediaFormat.KEY_DURATION);break;}}if(video<0){probe.release();throw new Exception("Нет видеодорожки");}if(to*1000000>length+200000){probe.release();throw new Exception("Конец находится за пределами видео");}probe.selectTrack(video);probe.seekTo((long)(from*1000000),MediaExtractor.SEEK_TO_NEXT_SYNC);long start=probe.getSampleTime(),end=Math.min(length,(long)(to*1000000));probe.release();if(start<0||start>=end)throw new Exception("Слишком короткий фрагмент между ключевыми кадрами");
  ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"Обрезка_"+System.currentTimeMillis()+".mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");values.put(MediaStore.Video.Media.RELATIVE_PATH,"Movies/ScreenRecorder");values.put(MediaStore.Video.Media.IS_PENDING,1);Uri out=c.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);if(out==null)throw new Exception("Нет места для копии");
  boolean ok=false;try(ParcelFileDescriptor fd=c.getContentResolver().openFileDescriptor(out,"rw")){MediaExtractor ex=new MediaExtractor();MediaMuxer mux=null;try{ex.setDataSource(c,input,null);mux=new MediaMuxer(fd.getFileDescriptor(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);HashMap<Integer,Integer> tracks=new HashMap<>();int capacity=1048576;for(int t=0;t<ex.getTrackCount();t++){MediaFormat f=ex.getTrackFormat(t);String mime=f.getString(MediaFormat.KEY_MIME);if(mime.startsWith("video/")||mime.startsWith("audio/")){tracks.put(t,mux.addTrack(f));ex.selectTrack(t);if(f.containsKey(MediaFormat.KEY_MAX_INPUT_SIZE))capacity=Math.max(capacity,f.getInteger(MediaFormat.KEY_MAX_INPUT_SIZE));}}MediaMetadataRetriever meta=new MediaMetadataRetriever();try{meta.setDataSource(c,input);String rotation=meta.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);if(rotation!=null)mux.setOrientationHint(Integer.parseInt(rotation));}finally{meta.release();}mux.start();ex.seekTo(start,MediaExtractor.SEEK_TO_PREVIOUS_SYNC);ByteBuffer buffer=ByteBuffer.allocateDirect(capacity);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int frames=0;while(ex.getSampleTrackIndex()>=0){long time=ex.getSampleTime();if(time>=end){ex.advance();boolean any=false;for(int k=0;k<ex.getTrackCount();k++){}if(time>end+2000000)break;continue;}if(time>=start){buffer.clear();int size=ex.readSampleData(buffer,0);if(size<0)break;info.set(0,size,time-start,ex.getSampleFlags());mux.writeSampleData(tracks.get(ex.getSampleTrackIndex()),buffer,info);frames++;}ex.advance();}if(frames==0)throw new Exception("Фрагмент пуст");mux.stop();ok=true;}finally{ex.release();if(mux!=null)mux.release();}}
  finally{if(!ok)c.getContentResolver().delete(out,null,null);}values.clear();values.put(MediaStore.Video.Media.IS_PENDING,0);c.getContentResolver().update(out,values,null,null);return out;
 }
}
